using System;using System.IO;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Mavis;
public static class AutoQaCheckpointProbe{
 static async Task Frames(int n){int f=Time.frameCount+n;var limit=DateTime.UtcNow.AddSeconds(8);while(Time.frameCount<f){if(!Application.isPlaying||DateTime.UtcNow>limit)throw new Exception("Frame stalled");await Task.Delay(5);}}
 public static async Task<object> Run(string take){if(!Application.isPlaying||SceneManager.sceneCount!=1||!string.IsNullOrEmpty(SceneManager.GetActiveScene().path)||CombatFeelPreview.Player||SessionState.GetBool("CombatCombinationTests",false))throw new Exception("Isolated unowned Play required");var rows=new List<object>();string error=null;float rootHeight=0;try{CombatFeelPreview.Spawn();var actor=CombatFeelPreview.Player;var motor=actor.GetComponent<ThirdPersonPlayerController>();motor.ExternalControlLock=true;await Frames(8);var death=actor.GetComponent<PlayerDeathRespawn>();var body=actor.GetComponent<CharacterController>();Vector3 foot=body.bounds.center-Vector3.up*body.bounds.extents.y;rootHeight=actor.transform.position.y-foot.y;var far=new GameObject("AUTO_QA far checkpoint");far.transform.SetParent(CombatFeelPreview.Camera.transform.parent,true);far.transform.position=foot+Vector3.right*20;var a=far.AddComponent<IslandRespawnPoint>();a.enabled=false;var near=new GameObject("AUTO_QA local checkpoint");near.transform.SetParent(far.transform.parent,true);near.transform.position=foot;var b=near.AddComponent<IslandRespawnPoint>();b.isDefault=false;b.activationRadius=3;
 death.SetCheckpoint(a);await Frames(4);rows.Add(new{ok=death.Checkpoint==b,label="Actor standing at checkpoint ground position activates radius 3"});death.SetCheckpoint(a);near.transform.position=foot+Vector3.right*3.25f;await Frames(4);rows.Add(new{ok=death.Checkpoint==a,label="Outside horizontal radius does not activate"});near.transform.position=foot-Vector3.up*3.25f;await Frames(4);rows.Add(new{ok=death.Checkpoint==a,label="Checkpoint on another vertical floor remains out of range"});near.transform.position=foot+Vector3.right*2.75f;await Frames(4);rows.Add(new{ok=death.Checkpoint==b,label="Inside horizontal radius at ground level activates"});death.SetCheckpoint(a);actor.GetComponent<PlayerHealth>().currentHealth=0;actor.GetComponent<PlayerHealth>().OnDeath.Invoke();near.transform.position=foot;await Frames(4);rows.Add(new{ok=death.Checkpoint==a,label="Dead player cannot activate another checkpoint"});}
 catch(Exception e){error=e.ToString();}finally{CombatFeelPreview.Clear();}var result=new{error,rootHeightAboveFeet=rootHeight,rows};File.WriteAllText("AUTO_QA/Evidence/"+take+".json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}
}